/**
 * Options Suite Tab Registry
 *
 * This file manages all tabs for the Options Suite app.
 * Provides comprehensive options trading tools and analysis.
 */

export const TABS = [
  {
    id: 'home',
    title: 'Home',
    load: () => import('./tabs/HomeTab'),
    meta: {
      description: 'Dashboard and overview of all options trading tools'
    }
  },
  {
    id: 'pricing',
    title: 'Pricing',
    load: () => import('./tabs/PricingTab'),
    meta: {
      description: 'Option pricing model with Greeks calculation'
    }
  },
  {
    id: 'option-chain',
    title: 'Option Chain',
    load: () => import('./tabs/OptionChainTab'),
    meta: {
      description: 'View and analyze option chains with pricing ladders'
    }
  },
  {
    id: 'payoff-analysis',
    title: 'Payoff Analysis',
    load: () => import('./tabs/PayoffAnalysisTab'),
    meta: {
      description: 'Visualize profit/loss scenarios and payoff diagrams'
    }
  }
];

// Helper function to get tab by ID
export function getTabById(id) {
  return TABS.find(tab => tab.id === id);
}

// Helper function to get all tab IDs
export function getAllTabIds() {
  return TABS.map(tab => tab.id);
}
