/**
 * Layout.jsx
 * Main layout component that provides consistent structure across all pages
 * Handles responsive design and overall page organization
 * Enhanced with premium glassmorphism effects and fixed navigation
 */

import React from 'react';

const Layout = ({ children }) => {
  return (
    <div className="min-h-screen text-light-text dark:text-dark-text transition-colors duration-300 flex flex-col bg-white dark:bg-gradient-to-br dark:from-slate-950 dark:via-slate-900 dark:to-slate-950">
      {/* Header/Navigation with Glass Effect - Fixed */}
      <header className="glass-nav fixed top-0 left-0 right-0 z-50">
        <div className="w-full px-4 sm:px-6 lg:px-8">
          {children[0]} {/* Navbar component */}
        </div>
      </header>

      {/* Main scrollable content with proper spacing for fixed header/footer */}
      <main className="flex-1 pt-24 pb-24 min-h-screen">
        <div className="max-w-[95%] mx-auto px-4 sm:px-6 lg:px-8 py-8">
          {children[1]} {/* Main content */}
        </div>
      </main>

      {/* Footer with glass effect - Fixed */}
      <footer className="glass-nav fixed bottom-0 left-0 right-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 text-center">
          <p className="text-sm text-gray-300 text-premium font-light">
            © 2025 Nick Skurka. Released under the MIT License.
          </p>
        </div>
      </footer>
    </div>
  );
};

export default Layout;
