/**
 * Financial Formula Suite Tab Registry
 *
 * This file manages all tabs for the Financial Formula Suite app.
 * To add a new tab:
 * 1. Create a new component in ./tabs/YourTab.jsx
 * 2. Export default React component and TAB_CONFIG from that file
 * 3. Add entry to TABS array below with lazy import
 * 4. Tab will automatically appear in the UI
 */

export const TABS = [
  {
    id: 'home',
    title: 'Home',
    load: () => import('./tabs/HomeTab'),
    meta: {
      description: 'Dashboard and overview of all financial formulas and tools'
    }
  },
  {
    id: 'compound-interest',
    title: 'Compound Interest',
    load: () => import('./tabs/CompoundInterestTab'),
    meta: {
      description: 'Calculate compound interest growth over time'
    }
  },
  {
    id: 'present-value',
    title: 'Present Value',
    load: () => import('./tabs/PresentValueTab'),
    meta: {
      description: 'Calculate the present value of future cash flows'
    }
  },
  {
    id: 'net-present-value',
    title: 'Net Present Value',
    load: () => import('./tabs/NetPresentValueTab'),
    meta: {
      description: 'Calculate net present value for investment analysis'
    }
  }
];

// Helper function to get tab by ID
export function getTabById(id) {
  return TABS.find(tab => tab.id === id);
}

// Helper function to get all tab IDs
export function getAllTabIds() {
  return TABS.map(tab => tab.id);
}
