/**
 * Navbar.jsx
 * Navigation component that handles tab switching and responsive mobile menu
 * Provides consistent navigation across all pages with smooth transitions
 * Enhanced with glassmorphism and modern visual effects
 */

import React, { useState } from 'react';
import { Menu, X, Moon, Sun, Home, TrendingUp, Zap, Gamepad2, Calculator, Wrench, Settings, Info, Package } from 'lucide-react';
import { useTheme } from '../context/ThemeContext';
import SearchBar from './SearchBar';

const Navbar = ({ tabs, activeTab, setActiveTab, onSearchNavigate }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const { isDark, toggleTheme } = useTheme();

  const handleTabClick = (tabId) => {
    setActiveTab(tabId);
    setIsMobileMenuOpen(false); // Close mobile menu on selection
  };

  // Get Lucide icon based on current tab
  const getTabIcon = (tabId) => {
    const iconMap = {
      home: Home,
      stockmarket: TrendingUp,
      productivity: Zap,
      games: Gamepad2,
      calculators: Calculator,
      physics: Wrench,
      suites: Package,
      settings: Settings,
      about: Info
    };
    return iconMap[tabId] || Home;
  };

  const CurrentIcon = getTabIcon(activeTab);

  return (
    <nav className="py-4">
      <div className="flex items-center justify-between w-full">
        {/* Logo/Brand - Far Left */}
        <div className="flex items-center space-x-3">
          <div className="p-2 glass-card micro-bounce">
            <CurrentIcon className="w-6 h-6" style={{color: 'rgb(0, 255, 145)'}} />
          </div>
          <h1 className="text-xl font-light text-white drop-shadow-sm text-premium tracking-tight">
            AllInOne Dashboard
          </h1>
        </div>

        {/* Desktop Navigation - Centered */}
        <div className="hidden md:flex space-x-2 absolute left-1/2 transform -translate-x-1/2">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => handleTabClick(tab.id)}
              className={`nav-tab ${activeTab === tab.id ? 'nav-tab-active' : 'nav-tab-inactive'}`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* Search and Controls - Far Right */}
        <div className="flex items-center space-x-4">
          {/* Search Bar - Desktop */}
          <div className="hidden lg:block">
            <SearchBar onNavigate={onSearchNavigate} />
          </div>

          {/* Theme Toggle */}
          <button
            onClick={toggleTheme}
            className="p-3 glass-card micro-bounce transition-all duration-300 hover:scale-110"
            aria-label="Toggle theme"
          >
            {isDark ?
              <Sun className="w-5 h-5 text-yellow-400" /> :
              <Moon className="w-5 h-5 text-blue-400" />
            }
          </button>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-3 glass-card micro-bounce"
            aria-label="Toggle mobile menu"
          >
            {isMobileMenuOpen ?
              <X className="w-5 h-5 text-gray-300" /> :
              <Menu className="w-5 h-5 text-gray-300" />
            }
          </button>
        </div>
      </div>

      {/* Mobile Navigation Menu */}
      {isMobileMenuOpen && (
        <div className="md:hidden mt-4 glass-card-strong rounded-2xl overflow-hidden">
          {/* Mobile Search */}
          <div className="p-4 border-b border-white/10">
            <SearchBar onNavigate={onSearchNavigate} />
          </div>

          {/* Mobile Menu Items */}
          <div className="p-2 space-y-1">
            {tabs.map((tab) => {
              const TabIcon = getTabIcon(tab.id);
              return (
                <button
                  key={tab.id}
                  onClick={() => handleTabClick(tab.id)}
                  className={`w-full text-left px-4 py-3 rounded-xl transition-all duration-300 text-premium
                             ${activeTab === tab.id
                               ? 'bg-gradient-to-r from-blue-700 to-slate-800 text-white shadow-lg'
                               : 'text-gray-300 hover:bg-white/10 hover:text-white'
                             }`}
                >
                  <div className="flex items-center space-x-3">
                    <TabIcon className="w-5 h-5" style={{color: 'rgb(0, 255, 145)'}} />
                    <span className="font-medium">{tab.label}</span>
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;
