import { useState, useEffect, useCallback } from 'react';
import { trackEvent } from '../utils/analytics';
import { tabs } from '../components/ProbabilitySuite/tabRegistry';

/**
 * Custom hook for managing Probability Suite state and navigation
 * Provides tab management, keyboard navigation, and analytics tracking
 */
const useProbabilitySuite = () => {
  const [selectedTab, setSelectedTab] = useState('home');

  // Load selected tab from localStorage on mount
  useEffect(() => {
    const savedTab = localStorage.getItem('probabilitySuite_selectedTab');
    if (savedTab && tabs.find(tab => tab.id === savedTab)) {
      setSelectedTab(savedTab);
    }
  }, []);

  // Save selected tab to localStorage and track analytics
  const selectTab = useCallback((tabId) => {
    const tab = tabs.find(t => t.id === tabId);
    if (!tab) return;

    setSelectedTab(tabId);
    localStorage.setItem('probabilitySuite_selectedTab', tabId);

    // Track analytics
    trackEvent('probability_suite_tab_selected', {
      tab_id: tabId,
      tab_title: tab.title,
      suite: 'probability'
    });
  }, []);

  // Navigate between tabs (for keyboard navigation)
  const navigateTab = useCallback((direction) => {
    const currentIndex = tabs.findIndex(tab => tab.id === selectedTab);
    let newIndex;

    switch (direction) {
      case 'next':
        newIndex = (currentIndex + 1) % tabs.length;
        break;
      case 'prev':
        newIndex = currentIndex === 0 ? tabs.length - 1 : currentIndex - 1;
        break;
      case 'first':
        newIndex = 0;
        break;
      case 'last':
        newIndex = tabs.length - 1;
        break;
      default:
        return;
    }

    selectTab(tabs[newIndex].id);
  }, [selectedTab, selectTab]);

  // Get data for currently selected tab
  const selectedTabData = tabs.find(tab => tab.id === selectedTab);

  // Track suite usage on mount
  useEffect(() => {
    trackEvent('probability_suite_opened', {
      suite: 'probability',
      initial_tab: selectedTab
    });
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  return {
    selectedTab,
    selectTab,
    tabs,
    navigateTab,
    selectedTabData
  };
};

export default useProbabilitySuite;
