/**
 * About.jsx
 * About page showing app categories, tech stack, and last updated date
 */

import React from 'react';
import { Calculator, Gamepad2, Clock, Circle, Package } from 'lucide-react';
import { BUILD_DATE } from '../utils/buildinfo.js';

const About = () => {
  const categories = [
    { name: 'Calculators', icon: Calculator, description: 'Financial and mathematical calculators', color: 'text-blue-500' },
    { name: 'Games', icon: Gamepad2, description: 'Interactive games and entertainment', color: 'text-purple-500' },
    { name: 'Tools', icon: Circle, description: 'Mathematical and utility tools', color: 'text-green-500' },
    { name: 'Productivity', icon: Clock, description: 'Time management and productivity apps', color: 'text-orange-500' },
    { name: 'Suites', icon: Package, description: 'Comprehensive application suites', color: 'text-red-500' }
  ];

  const technologies = [
    'React 18.3.1',
    'JavaScript',
    'Tailwind CSS 3.4.17',
    'HTML Canvas',
    'React Router DOM 6.28.0'
  ];

  // Format the build date for display
  const getFormattedBuildDate = () => {
    try {
      const buildDate = new Date(BUILD_DATE);
      return buildDate.toLocaleString('en-US', {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: true
      });
    } catch (error) {
      console.error('Error formatting build date:', error);
      return 'Build date unavailable';
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">

      {/* App Categories */}
      <div className="mb-12">
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-white mb-6">
          App Categories
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {categories.map((category, index) => {
            const Icon = category.icon;
            return (
              <div key={index} className="flex items-center space-x-3 p-4 bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700">
                <Icon className={`h-5 w-5 ${category.color}`} />
                <div>
                  <h3 className="font-medium text-gray-900 dark:text-white">{category.name}</h3>
                  <p className="text-sm text-gray-600 dark:text-gray-300">{category.description}</p>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Technologies Used */}
      <div className="mb-12">
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-white mb-6">
          Technologies Used
        </h2>
        <div className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 p-6">
          <ul className="space-y-2">
            {technologies.map((tech, index) => (
              <li key={index} className="text-gray-700 dark:text-gray-300">
                • {tech}
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* Last Updated */}
      <div>
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-white mb-6">
          Last Updated
        </h2>
        <div className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 p-6">
          <p className="text-gray-700 dark:text-gray-300">
            {getFormattedBuildDate()}
          </p>
        </div>
      </div>

    </div>
  );
};

export default About;
