/**
 * Suites.jsx
 * Suites page - comprehensive application suites with extensive functionality
 * Houses larger, more complex applications that contain multiple micro-apps
 */

import React from 'react';
import { Package, TrendingUp, Target, BarChart3 } from 'lucide-react';
import FinancialFormulaSuite from '../components/FinancialFormulaSuite/FinancialFormulaSuite';
import OptionsSuite from '../components/OptionsSuite/OptionsSuite';
import ProbabilitySuite from '../components/ProbabilitySuite/ProbabilitySuite';
import ModulePage from '../components/ModulePage';

const Suites = ({ searchNavigation }) => {
  // Available suite modules - comprehensive applications with multiple sub-tools
  const suiteModules = [
    {
      id: 'financial-formula-suite',
      title: 'Financial Formula Suite',
      description: 'Comprehensive library of financial formulas and calculators for investment analysis, risk assessment, and portfolio management. Contains multiple specialized tools for compound interest, present value, portfolio allocation, risk assessment, and market volatility analysis.',
      icon: TrendingUp,
      status: 'available',
      component: FinancialFormulaSuite
    },
    {
      id: 'options-suite',
      title: 'Options Suite',
      description: 'Complete options trading analysis toolkit with Black-Scholes pricing, Greeks calculation, strategy analysis, option chains, and payoff diagrams. Professional-grade tools for options traders and analysts.',
      icon: Target,
      status: 'available',
      component: OptionsSuite
    },
    {
      id: 'probability-suite',
      title: 'Probability Suite',
      description: 'Advanced probability analysis tools including distributions, statistical tests, and regression analysis. Essential for data-driven decision making and risk assessment.',
      icon: BarChart3,
      status: 'available',
      component: ProbabilitySuite
    }
    // Future suites can be added here, such as:
    // - Engineering Suite (structural calculations, electrical formulas, etc.)
    // - Medical Suite (dosage calculators, BMI tools, medical formulas)
    // - Educational Suite (learning modules, quiz systems, progress tracking)
    // - Business Suite (accounting tools, project management, analytics)
  ];

  return (
    <ModulePage
      title="Application Suites"
      icon={Package}
      modules={suiteModules}
      searchNavigation={searchNavigation}
      colorTheme="red"
      category="suites"
      eventPrefix="suite"
      buttonText="Launch Suite"
      description="Comprehensive application suites containing multiple specialized tools and extensive functionality for professional workflows."
    />
  );
};

export default Suites;
