import React, { Suspense, useEffect, useRef } from 'react';
import { Home, Calculator, Target, BarChart3, Layers } from 'lucide-react';
import useOptionsSuite from '../../hooks/useOptionsSuite';

/**
 * Options Suite - Main Application Component
 *
 * Features:
 * - Fixed horizontal tab bar on mobile (under navbar)
 * - Desktop vertical tab navigation with red theming
 * - Comprehensive options trading analysis tools
 * - Black-Scholes pricing, Greeks, strategies, and payoff analysis
 */
export default function OptionsSuite({ searchNavigation }) {
  const { selectedTab, selectTab, tabs, navigateTab, selectedTabData } = useOptionsSuite();
  const tabListRef = useRef(null);

  // Handle search navigation - automatically navigate to specific tool when coming from search/home
  useEffect(() => {
    if (searchNavigation && searchNavigation.toolId) {
      // Map tool IDs to tab IDs if needed
      const toolToTabMap = {
        'options-suite': 'home', // Default to home tab for the suite itself
      };

      const targetTab = toolToTabMap[searchNavigation.toolId] || 'home';
      selectTab(targetTab);
    }
  }, [searchNavigation, selectTab]);

  // Tab icons mapping
  const tabIcons = {
    home: Home,
    'pricing': Calculator,
    'option-chain': Layers,
    'payoff-analysis': BarChart3
  };

  // Keyboard navigation handler
  useEffect(() => {
    const handleKeyDown = (event) => {
      if (!tabListRef.current?.contains(document.activeElement)) return;

      switch (event.key) {
        case 'ArrowDown':
          event.preventDefault();
          navigateTab('next');
          break;
        case 'ArrowUp':
          event.preventDefault();
          navigateTab('prev');
          break;
        case 'Home':
          event.preventDefault();
          navigateTab('first');
          break;
        case 'End':
          event.preventDefault();
          navigateTab('last');
          break;
        case 'Enter':
        case ' ':
          event.preventDefault();
          break;
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [navigateTab]);

  // Render the selected tab content with lazy loading
  const renderTabContent = () => {
    if (!selectedTabData) return <div>Tab not found</div>;

    const LazyComponent = React.lazy(selectedTabData.load);

    return (
      <Suspense
        fallback={
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-red-500"></div>
            <span className="ml-3 text-gray-600 dark:text-gray-400">Loading...</span>
          </div>
        }
      >
        <LazyComponent />
      </Suspense>
    );
  };

  return (
    <>
      {/* Fixed Mobile Tab Bar - Always visible at top of screen under main navbar */}
      <div className="lg:hidden fixed top-16 left-0 right-0 z-50 bg-white/90 dark:bg-gray-900/90 backdrop-blur-md border-b border-gray-200/30 dark:border-gray-700/30 shadow-sm">
        <nav aria-label="Options Suite Navigation" className="max-w-7xl mx-auto px-4">
          <div
            role="tablist"
            className="flex gap-2 overflow-x-auto scrollbar-hide py-3"
            aria-orientation="horizontal"
            style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
          >
            {tabs.map((tab) => {
              const Icon = tabIcons[tab.id] || Calculator;
              const isSelected = tab.id === selectedTab;

              return (
                <button
                  key={tab.id}
                  role="tab"
                  tabIndex={isSelected ? 0 : -1}
                  aria-selected={isSelected}
                  aria-controls={`panel-${tab.id}`}
                  onClick={() => selectTab(tab.id)}
                  className={`
                    flex items-center gap-2 px-4 py-2 rounded-lg whitespace-nowrap flex-shrink-0
                    font-light tracking-wide transition-all duration-200
                    focus:outline-none focus:ring-2 focus:ring-red-500/30
                    ${isSelected
                      ? 'bg-red-500 text-white shadow-lg shadow-red-500/25'
                      : 'bg-white/70 dark:bg-gray-800/70 text-gray-700 dark:text-gray-300 hover:bg-red-50 dark:hover:bg-red-900/20 hover:text-red-600 dark:hover:text-red-400'
                    }
                  `}
                >
                  <Icon className="w-4 h-4 flex-shrink-0" />
                  <span className="text-sm font-medium">{tab.title}</span>
                </button>
              );
            })}
          </div>
        </nav>
      </div>

      {/* Main Application Layout */}
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 lg:pt-0 pt-20">
        <div className="flex h-screen">
          {/* Desktop Sidebar - Hidden on mobile */}
          <nav className="hidden lg:flex lg:w-80 lg:flex-col lg:border-r lg:border-gray-200/30 lg:dark:border-gray-700/30 lg:bg-white/70 lg:dark:bg-gray-900/70 lg:backdrop-blur-xl">
            {/* Suite Header */}
            <div className="flex items-center gap-4 p-6 border-b border-gray-200/30 dark:border-gray-700/30">
              <div className="p-2 bg-gradient-to-br from-red-500 to-red-600 rounded-lg shadow-lg">
                <Target className="h-6 w-6 text-white" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-gray-900 dark:text-white font-light tracking-wide">
                  Options Suite
                </h1>
                <p className="text-sm text-gray-500 dark:text-gray-400 font-light">
                  Everything related to your future rights (or obligations) to transact shares
                </p>
              </div>
            </div>

            {/* Desktop Tab Navigation */}
            <div className="flex-1 overflow-y-auto p-6">
              <ul
                ref={tabListRef}
                role="tablist"
                className="space-y-2"
                aria-orientation="vertical"
              >
                {tabs.map((tab) => {
                  const Icon = tabIcons[tab.id] || Calculator;
                  const isSelected = tab.id === selectedTab;

                  return (
                    <li key={tab.id} role="none">
                      <button
                        role="tab"
                        tabIndex={isSelected ? 0 : -1}
                        aria-selected={isSelected}
                        aria-controls={`panel-${tab.id}`}
                        onClick={() => selectTab(tab.id)}
                        className={`
                          w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left
                          font-light tracking-wide transition-all duration-200
                          focus:outline-none focus:ring-2 focus:ring-red-500/30
                          ${isSelected
                            ? 'bg-gradient-to-r from-red-500/20 to-red-600/20 text-red-600 dark:text-red-400 glow-red border border-red-200/30'
                            : 'text-gray-700 dark:text-gray-300 hover:bg-white/5 hover:text-red-600 dark:hover:text-red-400'
                          }
                        `}
                      >
                        <Icon className="w-5 h-5 flex-shrink-0" />
                        <span className="truncate">{tab.title}</span>
                      </button>
                    </li>
                  );
                })}
              </ul>
            </div>
          </nav>

          {/* Content Area */}
          <main className="flex-1 min-w-0">
            <div
              id={`panel-${selectedTab}`}
              role="tabpanel"
              tabIndex={0}
              aria-labelledby={`tab-${selectedTab}`}
              className="p-8 rounded-2xl bg-white/5 dark:bg-black/30 backdrop-blur-md border border-white/10 min-h-[600px] focus:outline-none focus:ring-2 focus:ring-red-500/30"
            >
              {renderTabContent()}
            </div>
          </main>
        </div>
      </div>
    </>
  );
}
